with exploded as (select id, customer_id, created_at, coupon_codes, attr_key, v from carts lateral view explode(attributes) li as attr_key, v) select date_trunc('hour', created_at) as hour_window, customer_id, max(created_at) as last_created_at, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes, max(created_at) as last_seen, size(collect_set(attr_key)) as num_attr_keys, count(*) as num_rows from exploded group by grouping sets ((date_trunc('hour', created_at), customer_id), (date_trunc('hour', created_at))) order by hour_window;
